    ["01-1"] = {name="Vallée des Épreuves", tips={{k="交通", text="Pour le départ commun, descends la grande route de Durotar vers le sud et entre dans la Vallée des Épreuves par l'est pour trouver Kaltunk."}, {k="取捨", text="Armes égarées, Les péons paresseux et les deux quêtes du Convent de la Lame ardente peuvent se regrouper en deux trajets."}, {k="取捨", text="Termine d'abord Les vils quasits (la quête des diablotins), puis prends Le médaillon de la Lame ardente auprès de la même Zureetha Fargaze.", s={{"Termine d'abord Les vils quasits (la quête des diablotins), puis prends Le médaillon de la Lame ardente auprès de la même Zureetha Fargaze.", {class={"WARLOCK"}}}}}, {k="提醒", text="En dessous du niveau 6? Tue des sangliers tachetés, des scorpides ouvriers ou des vils quasits sur le chemin de Sen'jin.", s={{"En dessous du niveau 6?"}, {"Tue des sangliers tachetés, des scorpides ouvriers ou des vils quasits sur le chemin de Sen'jin"}}}}, danger={[1]="Au tournant du Convent de la Lame ardente, tu risques d'attirer plusieurs vils quasits. Nettoie l'entrée avant de prendre la pioche pour garder une sortie."}, grind={[1]={mob="Sanglier tacheté", note="Monstres normaux, densité élevée, pour la plupart neutres. Tire-les une par une au nord de la Vallée des Épreuves pour La dent tranchante aux niveaux 1 et 2."}, [2]={mob="Scorpide ouvrier", note="Beaucoup de créatures ordinaires, surtout neutres, au nord-ouest de L'Antre. Attire-les une par une pendant L'aiguillon du scorpide."}, [3]={mob="Vil quasit", note="Beaucoup de créatures normales près du Convent de la Lame ardente. Attire-les une par une depuis l'extérieur. Atteins le niveau 6 avant de quitter la vallée."}}, supply={[1]={npc="Rarc"}, [2]={npc="Zlagk"}, [3]={npc="Duokna"}}, steps={[1]={npc="Kaltunk", tgt="Kaltunk"}, [2]={npc="Gornek", tgt="Gornek"}, [3]={npc="Bon-cadeau (Vallée des épreuves)", npcObj=true, tag="Facultatif", desc="Ne l'accepte que si tu possèdes un bon cadeau de la Vallée des Épreuves. Le bon cadeau est un objet de départ présent dans le sac des personnages de la race d'origine. Fais un clic droit dessus directement; il n'y a pas de point d'obtention sur la carte."}, [4]={hint="Apporter le Bon-cadeau (Vallée des Epreuves) à Magga.", tag="Facultatif", desc="N'accepte la quête que si tu as le bon-cadeau de la Vallée des Épreuves."}, [5]={npc="Magga", tgt="Magga", tag="Facultatif", desc="N'accepte la quête que si tu as le bon-cadeau de la Vallée des Épreuves."}, [6]={npc="Gornek", tgt="Gornek"}, [7]={npc="Gornek", tgt="Gornek"}, [8]={hint="Tuer 10 Sangliers tachetés, puis retourner voir Gornek, dans l'Antre."}, [9]={npc="Hana'zua", tgt="Hana'zua"}, [10]={hint="Tuer Sarkoth et rapporter sa pince à Hana'zua."}, [11]={npc="Hana'zua", tgt="Hana'zua"}, [12]={npc="Hana'zua", tgt="Hana'zua"}, [13]={hint="Récupérez 6 armes d'entraînement abandonnées, puis retournez auprès de Kzan Trancheronce, dans l'Antre."}, [14]={npc="Gornek", tgt="Gornek"}, [15]={hint="Informer Gornek, à l'Antre, de la situation critique dans laquelle se trouve Hana'zua."}, [16]={npc="Kzan Thornslash", tgt="Kzan Thornslash"}, [17]={npc="Gornek", tgt="Gornek"}, [18]={npc="Gornek", tgt="Gornek"}, [19]={npc="Galgar", tgt="Galgar"}, [20]={npc="Contremaître Thazz'ril", tgt="Contremaître Thazz'ril"}, [21]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [22]={text="Nettoie d'abord la vallée de départ, puis va à la grotte au nord"}, [23]={hint="Apporter 10 Queues de scorpides ouvriers à Gornek, dans l'Antre."}, [24]={hint="Apportez à Galgar 10 Pommes de cactus. Il vous a précisé qu'elles se trouvaient souvent à côté des cactus."}, [25]={hint="Utiliser la Masse du contremaître sur les Péons paresseux, lorsqu'ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Masse du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves.", desc="Réveille cinq péons endormis avec le gourdin du contremaître."}, [26]={hint="Tuer 12 Vils quasits.", desc="Les démonistes font plutôt la quête du diabloti