    [91755] = {n="Massifs élagués", d="Récupérez 12 feuilles verdoyantes sur des massifs corrompus dans les contreforts du mont Hyjal.", tgo={{"Massif corrompu"}}},
    [91770] = {n="Érosion d'écorce", d="Appliquez le cataplasme sur Fraxinus.", tgo={{"Fraxinus"}}},
