    [91883] = {n="La lance du seigneur du ciel", d="Tuez Zarrat Aile-de-ver et rendez sa lance à Omnuron.", tgo={{"Zarrat Aile-de-ver"}}},
    [91920] = {n="Yeux sauvages", d="Récupérez 3 yeux de Murlocs et apportez-les à l'apothicaire Renferrel au Sépulcre.", tgo={{"Enfourneur", "Ecumeur Branchie-bleue", "Chasse-marée murloc", "Chasseur Grisebrume", "Oracle Grisebrume", "Oracle murloc", "Prophète Grisebrume", "Oracle mineur murloc"}}},
    [91921] = {n="Retour vers Quinn (encore une fois)", d="Apporter la potion de Quinn à Quinn Yorick au lopin d'Ivar, au nord du Sépulcre."},
    [91923] = {n="Celastrus l'Amer", d="Trouvez Celastrus l'Amer et détruisez-le, puis retournez voir Thylaen avec sa fronde brisée.", tgo={{"Celastrus l'Amer"}}},
    [91952] = {n="La corruption et sa source", d="Trouvez l'ermite Ketharas au mont Hyjal."},
    [92008] = {n="Pièces de premier choix", d="Récupérez la commande de pièces détachées de Kaylaena Murmeprintemps auprès de Numi, à Long-Guet."},
    [92009] = {n="Cargaison délicate", d="Transportez délicatement la caisse de pièces et de babioles jusqu'à Kaylaena Murmeprintemps au mont Hyjal."},
    [92016] = {n="Examen radiculaire", d="Entrez dans le Puits d'éternité et examinez les racines de Nordrassil."},
    [92017] = {n="Vents purificateurs", d="Obtenez 5 grandes plumes d'hippogriffe et 3 poils de chimère huileux pour Marn.", tgo={{"Saute-vents des montagnes"}, {"Chimaerok soufflevif"}}},
    [92020] = {n="Le Grand Livre des gros lézard d'Hol'anyee", d="Apportez Le Grand Livre des gros lézards d'Hol'anyee à un druide au sommet du mont Hyjal."},
