    [95766] = {n="Une prodigieuse amie à plumes", d="Trouvez l'étrange oiseau des terres corrompues du versant sud-ouest."},
    [95770] = {n="À la recherche de la cité perdue", d="Explorez le récif Infâme et trouvez l'entrée de la grotte."},
    [95773] = {n="Des adversaires sous les flots", d="Récupérez 10 tridents d'écaille-de-mer sur des tirailleurs écaille-de-mer.", tgo={{"Tirailleur écaille-de-mer"}}},
    [95774] = {n="Son nom est Olgra", d="Tuez des Hurans et récupérez 4 parures d'Olgra pour le mémorial de Mankrik.", tgo={{"Pillard tranchecrin"}}},
    [95775] = {n="La cité Submergée", d="Utilisez la peau et le charbon pour créer des reproductions des tablettes trouvées dans la cité Submergée."},
    [95776] = {n="Le seul bon Écaille-de-mer…", d="Tuez Var'Taka dans la cité Submergée."},
    [95789] = {n="Sel-augures véreux", d="Récupérez 10 artéfacts imprégnés de vaudou sur les pirates sel-augures de la cité Submergée."},
    [95791] = {n="Le capitaine sel-augure", d="Éliminez 3 légistes sel-augures ainsi que le capitaine Lèveffroi dans la cité Submergée."},
    [95803] = {n="Un gage de bonne volonté", d="Apportez la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse."},
    [95805] = {n="Grâce d'An'she et Mu'sha", d="Portez l'encens fumant jusqu'au sanctuaire de An'she et de Mu'sha, dans les collines au sud-est. Vous avez dix minutes avant que l'encens ne soit réduit en cendres !", star={"Bourse en cuir brûlée"}},
    [95882] = {n="AVIS DE RECHERCHE : maître-éclaireur Vargas", d="Apportez l'œil du maître-éclaireur à Neza Flaire-Sang à Rog'mar.", tgo={{"Maître-éclaireur Vargas"}}},
    [95926] = {n="Le cristal ténébreux", d="Récupérez un fragment de cristal épuisé, incolore, près du cristal achromatique, sur la terrasse du Façonneur."},
    [95928] = {n="Éléments cristallins", d="Apportez un cristal humide, un cristal chargé, un cristal nocif et un cristal ardent de la terrasse des Façonneurs à Mayena Chercheterre."},
    [95951] = {n="L'art de la lance", d="Récupérez du bois dans les tas de bois de paysan au camp de bûcherons de Turner, puis taillez-les en 20 lances transperçantes de fortune."},
    [95955] = {n="Brochettes de crocilisque", d="Empalez 10 crocilisques d'eau douce, puis retournez voir Tan'jani, à Rog'mar.", tgo={{"Crocilisque d'eau douce"}}},
    [95981] = {n="Routes sous surveillance", d="Tuez 8 sorciers de Dalaran et 8 guetteurs de Dalaran pour le prêtre des ombres Allister au Sépulcre.", tgo={{"Gardien de Dalaran"}, {"Sorcier de Dalaran"}}},
    [96010] = {n="Des fragments de pylône", d="Récupérez des éclats et des fragments de pylône, conservés sous bonne garde dans les villages des Magram et des Gelkis. Rapportez-les à Mordent Ombrégale."},
    [96018] = {n="Alimenter les pylônes", d="Obtenez le tamis de mana à l'intérieur du temple de Shen'dralas et utilisez-le pour collecter des cristaux de mana ancestral. Quand vous avez suffisamment de mana, renforcez les pylônes et retournez voir Mordent Ombrégale."},
    [96026] = {n="Deuxième étape : plus de pierres", d="Apportez 10 pierres de lest lourdes à Hamur, à Bolder'ok."},
    [96063] = {n="Du gaz en or", d="Récupérez 8 fioles d'émanations du marécage pour Slibo Bekdanlo."},
    [96067] = {n="On se défoule !", d="Aidez Slibo à tester sa création."},
    [96078] = {n="Une histoire au coin du feu", d="Apportez les reproductions des tablettes au maître Gadrin, au village de Sen'jin, à Durotar."},
    [96101] = {n="Les grands espaces sauvages", d="Asseyez-vous près du feu de camp basique de Raan et attendez de recevoir l'amélioration Repos amplifié.", objs={"Basic Campfire"}},
    [96102] = {n="Introduction au camping : la couture", d="Parlez à Snang, à Orgrimmar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main.", tgo={{"Snang"}}},
    [96103] = {n="Un festin pour les busards", d="Apportez le crâne rongé à Neza Flaire-Sang, à Rog'mar."},
    [96104] = {n="Le chant du trotteur", d="Apportez un bec de haut-trotteur intact à Neza Flaire-Sang, à Rog'mar.", tgo={{"Haut-trotteur en maraude"}}},
    [96105] = {n="Le roi des plaines Sauvages", d="Utilisez l'appel des hauts-trotteurs pour appeler le chef de la troupe de lions. Tuez la bête et récupérez sa peau pour Neza Flaire-Sang à Rog'mar.", tgo={{"Ombassa"}}},
    [96107] = {n="Des plumes pour l'empennage", d="Apportez 6 plumes de busard des plaines à Neza Flaire-Sang, à Rog'mar.", tgo={{"Busard des basses plaines"}}},
    [96108] = {n="Flèches empoisonnées", d="Apportez 4 échantillons de venin de vipère de la clairière à Neza Flaire-Sang, à Rog'mar.", tgo={{"Vipère de la clairière"}}},
    [96109] = {n="Le carquois d'une chasseuse", d="Rapportez 6 peaux de lion prisées à Neza Flaire-Sang, à Rog'mar.", tgo={{"Patriarche des plaines sauvages", "Chasseresse des plaines sauvages"}}},
    [96130] = {n="Chakuyak", d="Abattez Chakuyak, puis rapportez sa fourrure.", tgo={{"Chakuyak"}}},
    [96131] = {n="Vieux débris et vieil ami", d="Apportez la branche diffusant une faible lueur à Ketharas."},
    [96145] = {n="Par-delà ailes et griffes", d="Retrouvez Phoebe Hauteplume au sanctuaire d'Aviana."},
    [96204] = {n="La colère de la Sculpte-vent", d="Accompagnez Lumina Chantelevent et aidez-la à s'échapper du donjon de Fenris.", tgo={{"Lumina Chantelevent"}}},
    [96209] = {n="Orokai l'ancien", d="Allez voir Orokai à Reflet-de-Lune."},
    [96252] = {n="Trésors ternis", d="Récupérez 8 bracelets hauteplumes ternis dans les nids des Harpies ailes-de-ver."},
    [96255] = {n="Amalgame de moelle", d="Tuez la gelée gangrecendre éveillée.", tgo={{"Awakened Fel Ash Slime"}}},
    [96262] = {n="Pommes de pin piquantes", d="Ramassez 10 pommes de pin piquantes aux pieds d'arbres sains."},
    [96296] = {n="Corruption fétide", d="Trouvez et enlevez 6 nœuds corrompus des arbres avoisinants.", objs={"Excroissance corrompue"}},
    [96302] = {n="Absolution totale", d="Prenez l'encens de Marn et laissez la fumée purifier l'air à proximité de la dépouille d'Archimonde."},
    [96303] = {n="Brume du souvenir", d="Utilisez la branche enchantée pour libérer 5 feux follets près de Nordrassil."},
    [96321] = {n="Le dieu mourant", d="Trouvez quelqu'un sur le mont Hyjal qui pourrait être intéressé par le bâton diffusant une faible lueur."},
    [96322] = {n="Une si amère vengeance", d="Parlez à Gangrechique."},
    [96332] = {n="La vengeance du noyé récalcitrant", d="Pénétrez dans la prison d'Alcaz, puis tuez 15 soldats strashaz ainsi que 8 enchanteresses strashaz. Rapportez également la tête de la maîtresse des marées Ca'zass à la sergente Ulka."},
    [96334] = {n="Foulards rouge sang", d="Pénétrez dans la prison d'Alcaz et récupérez 8 foulards rouge sang sur les Humains qui s'y trouvent."},
    [96335] = {n="L'homme aux chaînes de fer", d="Récupérez la clé de menottes d'Alcaz sur l'Interrogateur dans la prison d'Alcaz."},
    [96369] = {n="Mauvaises nouvelles pour Folkar", d="Retournez voir le commandant Folkar."},
    [96395] = {n="Une rancune ancestrale", d="Apaisez l'esprit de Faldrim Courbenclume, puis retournez voir la domestique fantomatique dans la salle des Thanes."},
    [96435] = {n="Une fin de circonstance", d="Jetez les ossements des démonistes dans le tas d'os près des flaques de gelée."},
    [96550] = {n="Rappel du combat", d="Utilisez le fourreau brodé pour parler au vétéran et découvrir son histoire au surplomb de Sylvancienne."},
    [96604] = {n="Les grands espaces sauvages", d="Asseyez-vous près du feu de camp basique de Brakk et attendez de recevoir l'amélioration Repos amplifié.", objs={"Basic Campfire"}},
    [96605] = {n="Les grands espaces sauvages", d="Asseyez-vous près du feu de camp basique de Kaga et attendez de recevoir l'amélioration Repos amplifié.", objs={"Basic Campfire"}},
    [96607] = {n="Les grands espaces sauvages", d="Asseyez-vous près du feu de camp basique d'Eleanor et attendez de recevoir l'amélioration Repos amplifié.", objs={"Basic Campfire"}},
    [96616] = {n="Des herbes pour traiter la douleur", d="Récupérez 12 silphiums d'Hyjal."},
    [96622] = {n="Un repos sans douleur", d="Livrez le cataplasme de silphium d'Hyjal à Enho et Maruke."},
    [96638] = {n="L'aventurier", d="Parlez à Raan Aile-sauvage près de Shen'dar."},
    [96646] = {n="Introduction au camping : la cuisine", d="Parlez à Zerril Douce-Brise à Shen'dar pour apprendre à cuisiner.", tgo={{"Zerril Douce-Brise"}}},
    [96652] = {n="L'aventurier", d="Apportez le journal à Brakk près de Tranchecolline."},
    [96655] = {n="Introduction au camping : la cuisine", d="Parlez au cuisinier Torka, à Tranchecolline, pour apprendre à cuisiner.", tgo={{"Cuisinier Torka"}}},
    [96658] = {n="Introduction au camping : la cuisine", d="Parlez à William Pickman, à Brill, pour apprendre à cuisiner.", tgo={{"William Pickman"}}},
    [96659] = {n="L'aventurière", d="Apportez le paquet de fournitures à Kaga Sabot-sauvage près de Sabot-de-Sang."},
    [96661] = {n="Introduction au camping : la cuisine", d="Parlez à Pyall Sabots-Feutrés, à Sabot-de-Sang, pour apprendre à cuisiner.", tgo={{"Pyall Silentstride"}}},
    [96774] = {n="L'idole des anciens Gurubashi", d="Récupérez une idole antique des Gurubashi dans la cité Submergée."},
    [96775] = {n="Tête de Zum'rah", d="Tuez le féticheur Zum'rah et rapportez sa tête à Mazu'kon, en Mulgore.", tgo={{"Sorcier-docteur Zum'rah"}}},
    [96779] = {n="Sabotage du Syndicat", d="Trouvez le seigneur Tomas dans le donjon de Fort-de-Durn, dans les contreforts de Hautebrande, et tuez-le. Revenez ensuite voir Myrokos Sourdeforme.", tgo={{"Seigneur Tomas"}}},
    [96781] = {n="Qu'est-ce qu'ils manigancent ?", d="Volez le rapport d'éclaireur de Barton, puis rapportez-le à Myrokos Sourdeforme, au manoir de Ravenholdt.", tgo={{"Barton"}}},
    [96783] = {n="Un moyen d'infiltration", d="Volez un uniforme du Syndicat au manoir de Nordclos afin d'infiltrer le donjon de Stromgarde."},
    [96784] = {n="Maître du déguisement", d="Portez le déguisement d'un membre du Syndicat, puis trouvez quelqu'un qui soit au courant de la transaction secrète au donjon de Stromgarde."},
    [96785] = {n="Motus", d="Dans le donjon de Stromgarde, trouvez de quoi convaincre Anastasia de vous révéler les détails de cette transaction secrète."},
    [96786] = {n="La piqûre du Syndicat", d="Interrompez la transaction secrète et récupérez l'objet destiné au Syndicat. Rapportez-le ensuite à Myrokos Sourdeforme, au manoir de Ravenholdt."},
    [96796] = {n="Atelier dans les bois", d="Apportez la pièce détachée à la bricoleuse du nom de Kaylaena dans la partie basse d'Hyjal."},
    [96821] = {n="Toutes pattes dehors", d="Tuez 6 rampantes noirecrêtes et 6 rôdeuses noirecrêtes dans le sud de Durotar, puis informez-en Gar'thok à Tranchecolline.", tgo={{"Rampante noirecrête"}, {"Rôdeuse noirecrête"}}},
    [96822] = {n="Pour l'honneur", d="Récupérez la hache d'armes d'écumeur, l'arc d'écumeur et le bouclier d'écumeur aux alentours du donjon de Tiragarde, puis rapportez-les à Turroc à Tranchecolline.", objs={"Arc d'écumeur", "Hache d'armes d'écumeur", "Bouclier d'écumeur"}},
    [96825] = {n="Ces fruits pourraient se défendre", d="Le cuisinier Torka de Tranchecolline souhaite que vous ramassiez 8 figues de Barbarie dans les terres des Tranchecrins à l'ouest de la ville.", objs={"Figue de Barbarie"}},
    [96830] = {n="Don de long-voyance", d="Cherchez des signes de la présence de la Horde au nord-ouest du mont Hyjal."},
    [96873] = {n="Une douleur dans la nuque", d="Pa'zula du village de Sen'jin vous demande de récupérer 3 résidus lumineux. Vous pourrez obtenir des résidus lumineux en désenchantant les pendentifs maléficiés obtenus sur les Trolls des îles de l'Écho."},
    [96876] = {n="Le sac perdu d'Ukor", d="Rapportez son sac à Ukor dans le sud de Durotar."},
    [96877] = {n="Le sabot d'Halikor", d="Rapportez le sabot d'Halikor à Orgrimmar."},
    [96895] = {n="L'émissaire de l'Aube d'argent", d="Trouvez le membre de l'Aube d'argent près de l'entrée de Fossoyeuse."},
    [96897] = {n="Le Culte des damnés", d="Tuez 8 néophytes sombres et 8 massacreurs sombres dans les clairières de Tirisfal.", tgo={{"Néophyte sombre"}, {"Massacreur sombre"}}},
    [96898] = {n="Les vestiges de la guerre", d="Rassemblez 12 fragments de cristal nécrotique dans les clairières de Tirisfal.", tgo={{"Néophyte sombre", "Massacreur sombre"}}},
    [96899] = {n="La forteresse de Bandarion", d="Retrouvez Leonid Barthalomew à la forteresse de Bandarion, dans les clairières de Tirisfal."},
    [96930] = {n="La corneille capricieuse", d="Retournez voir le corbeau curieux."},
    [96931] = {n="En haut de la montagne", d="Touchez l'effigie de la corneille située sur le pont surplombant le Berceau de la tranquillité pour invoquer la déesse sauvage, Jereman."},
    [96939] = {n="L'équilibre entre la vie et la mort", d="Parlez au dieu sauvage Marrosis."},
    [96957] = {n="Reposer ses vieux os", d="Récoltez 20 os blanchis par le soleil."},
    [96964] = {n="Une créature intelligente", d="Parlez au dieu sauvage Renalard."},
    [96971] = {n="Plus rusé qu'un démon", d="Récupérez 8 paquets de fournitures abandonnées."},
    [96978] = {n="Venaison violente", d="Parlez au dieu sauvage Kala'th."},
    [96979] = {n="Sacré rafraîchissement", d="Remplissez la goudre de Galvinquam Feuilsyre à la cascade un peu plus loin."},
    [96984] = {n="Cœur de la perturbation", d="Récupérez le granule arcanique pour le magus Wordeen Toisevide à Moulin-de-Tarren."},
    [96986] = {n="Le Chevalier de la tombe", d="Triomphez d'Atrexis le Chevalier de la tombe dans la cité de Dalaran pour Melisara à Moulin-de-Tarren."},
    [96987] = {n="Éducation opportuniste", d="Récupérez La fondation de Dalaran dans la cité de Dalaran pour Rexxie Pincentime près de l'entrée des égouts."},
    [96988] = {n="Source de pouvoir", d="Récupérez 6 noyaux de sentinelles fissurés dans la cité de Dalaran pour le docteur Martin Felben à Fossoyeuse.", objs={"Factionnaire fragmenté"}},
    [96991] = {n="Assistance d'expédition", d="Apportez les affaires de Galvinquam à Marn Eucorne au sommet."},
    [97022] = {n="Rendre compte à Danitha", d="Parlez à Danitha Morr à la forteresse de Bandarion."},
    [97049] = {n="Essence de gelées suintantes", d="Récupérez 8 essences de gelée suintante à la terrasse du Façonneur."},
    [97196] = {n="L'Œil du Porte-froid", d="Récupérez l'œil du Porte-froid dans les souilles de Tranchebauge."},
    [97198] = {n="Magie noiregueule", d="Récupérez un totem rituel noiregueule au repaire des Noiregueules."},
    [97223] = {n="La matriarche griffesang", d="Apportez les œufs de la matriarche griffesang à Xar'Ti, au village de Sen'jin.", tgo={{"Matriarche griffesang"}}},
    [97225] = {n="Idoles de Loa oubliées", d="Récupérez 8 idoles de Loas oubliées sur les îles de l'Écho. Apportez-les au maître Gadrin, au village de Sen'jin.", objs={"Idole de Loa oubliée"}},
    [97243] = {n="L'appel du feu", d="Apportez la torche de la flamme dormante à Olariaan Vivebrûle au sanctuaire des Flammes, dans les plaines Aérelles."},
    [97244] = {n="L'appel du feu", d="Tuez le prêtre céleste Faladiel dans les plaines Aérelles, puis récupérez son cœur.", tgo={{"Prêtre céleste Faladiel"}}},
    [97245] = {n="L'appel du feu", d="Trouvez le repaire de Kuramaa dans les hautes-terres de Shen'dar et vainquez l'esprit au combat. Une fois victorieux, rapportez le masque de Kuramaa à Olariaan Vivebrûle dans les plaines Aérelles.", tgo={{"Kuramaa"}}},
    [97250] = {n="Accusé à tort, corrigé à raison", d="Tuez des soldats de l'Alliance qui empiètent sur les Tarides, à la frontière du marécage d'Âprefange. Puis retournez voir le grunt Logmar, au camp Taurajo.", tgo={{"Soldat envahissant"}, {"Pilleur indigné"}}},
    [97253] = {n="Foire à la ferraille", d="Récupérez 5 poignées de pièces complexes au camp des pirates, au sud de Cabestan, puis retournez voir Wrenix le Misérable, à Cabestan.", objs={"Tas de pièces complexes"}},
    [97257] = {n="L'appel du feu", d="Attendez qu'Olariaan commence le rituel au brasero d'offrande, puis suivez ses instructions.\nVous devez remettre la flamme éternelle à Valanaar avant la fin du temps imparti.", tgo={{"Brasero d'offrande"}, {"Brasero de la flamme éternelle"}}, star={"Totem des flammes chargées", {"SHAMAN"}}},
    [97265] = {n="Furie contre les Fielfuries", d="Éliminez différents Satyres fielfuries à Sargeron, en Désolace, puis retournez auprès d'Aka'rai au village de Proie-de-l'Ombre.", tgo={{"Entourloupeur Fielfurie"}, {"Implorateur de l'enfer Fielfurie"}, {"Traqueur des ténèbres Fielfurie"}, {"Lige de la corruption Fielfurie"}, {"Voleur Fielfurie"}}},
    [97279] = {n="Armes égarées", d="Récupérez 6 armes d'entraînement abandonnées, puis retournez auprès de Kzan Trancheronce, dans l'Antre.", objs={"Arme d'entraînement abandonnée"}},
    [97281] = {n="Une tempête en approche", d="Apportez l'orbe de tempête émoussé à Rezlak, près du ravin Asséché."},
    [97282] = {n="Un potentiel houleux", d="Apportez 5 organes de lézard-tonnerre chargés à Rezlak, près du ravin Asséché.", tgo={{"Lézard-tonnerre", "Foudroyant", "Halikor"}}},
    [97287] = {n="Négociations avisées", d="Allez parler à l'image de l'archimage Modera, près de Dalaran."},
    [97288] = {n="Tourment interminable", d="Apportez la tête abominable au maître apothicaire Faranell à Fossoyeuse."},
    [97289] = {n="Tourment interminable", d="Apportez la tête du baron au corps d'Othmar, à Fossoyeuse."},
    [97290] = {n="Tourment interminable", d="Faites votre rapport au maître apothicaire Faranell, à Fossoyeuse."},
    [97291] = {n="Tourment interminable", d="Récupérez un calot toxique auprès de Grisette Fauve dans le quartier des Marchands, de la cloquette auprès de la maîtresse des herboristes et de l'essence d'agonie auprès du marchand de poison du quartier des Voleurs, pour le maître apothicaire Faranell à Fossoyeuse.", objs={"Cloquette"}},
    [97292] = {n="Tourment interminable", d="Injectez le sérum sifflant dans le dispositif au-dessus du corps d'Othmar, pour le maître apothicaire Faranell.", objs={"Othmar's Head"}},
    [97319] = {n="Un cousin à l'étranger", d="Retrouvez le cousin disparu quelque part sur le mont Hyjal."},
    [97327] = {n="Bourses noiregueules", d="Entrez dans le repaire des Noiregueules et récupérez 5 bourses noiregueules pour Ekkal, qui se trouve dans les ruines d'Eldarath en Azshara.", tgo={{"Berserker noiregueule", "Esclave noiregueule", "Chasseur de têtes noiregueule", "Diablotin grouillant", "Tueur legashi", "Champion noiregueule", "Satyre Legashi"}}},
    [97328] = {n="Tout ce qui vaut cher", d="Récupérez 8 cargaisons volées dans les ruines de Zul'Kunda, dans la vallée de Strangleronce, et apportez vos trouvailles à quelqu'un, à Baie-du-Butin."},
    [97329] = {n="Où est la clé ?", d="Obtenez la clé primitive auprès des Trolls des ruines de Zul'Kunda, dans la vallée de Strangleronce, et apportez-la à Zimmix Krachétincelle.", tgo={{"Eclaireur Bloodscalp", "Chasseur Bloodscalp", "Berserker Bloodscalp", "Sorcier-docteur Bloodscalp", "Chasseur de tête Bloodscalp", "Belluaire Bloodscalp", "Mystique Bloodscalp"}}},
    [97331] = {n="La grande évasion de Zimmix", d="Conduisez Zimmix Krachétincelle hors des ruines de Zul'Kunda, puis informez le maître des quais Lozouïe de votre sauvetage."},
    [97332] = {n="Une confiance deux fois mal placée", d="Apportez le paquet doublement renouvelé au maître des quais Sifflebruit, au port de Poudremèche, sur les rives Claires."},
    [97386] = {n="L'offensive de Grom'gol", d="Le commandant Aggro'gosh du campement Grom'gol vous demande de tuer des Ogres au tertre des Ogres mosh'Ogg.", tgo={{"Magicien Mosh'Ogg"}, {"Combattant Mosh'Ogg"}, {"Mutileur Mosh'Ogg"}, {"Chaman Mosh'Ogg"}}},
    [97453] = {n="Tonte des mauvaises herbes", d="Tuez 6 herbes carnivores au sud de Grom'gol, puis informez la mère de Gemmil.", tgo={{"Herbe carnivore"}}},
    [97485] = {n="Traditions des pitons", d="Achetez un paquet d'herbes à Nida l'herboriste, un fagot de brindilles de cèdre à Nata la fournisseuse de composants d'enchantements, des fibres tendineuses à Mahu le fournisseur de matériel de travail du cuir, ainsi que du silex et de l'amadou de cérémonie à Naal le fournisseur de matériel de cuisine.\nCombinez ces composants, puis répandez l'encens depuis la cime des Chasseurs.", objs={"Brûle-encens"}},
    [97530] = {n="Collecte chez les Cognedunes", d="Le chef de la sécurité Bilgewhizzle du port Gentepression en Tanaris veut que vous retrouviez un bracelet particulièrement brillant perdu près de la base des Ogres cognedunes.", tgo={{"Ogre Cognedune", "Massacreur Cognedune", "Ogre-mage Cognedune", "Brute Cognedune", "Démoniste Cognedune"}}},
    [97534] = {n="Dans le cambouis", d="Quinn vous demande de collecter 7 débris du désert et de les lui rapporter à Gadgetzan."},
